				} });","import { createCustomElement, actionTypes } from '@servicenow/ui-core';
import snabbdom from '@servicenow/ui-renderer-snabbdom';
import styles from './styles.scss';
import camera_icon from '../../tile-icon/camera.svg';

const { COMPONENT_DOM_READY,COMPONENT_PROPERTY_CHANGED } = actionTypes;
const SHOW_CAMERA_VIDEO = "SHOW_CAMERA_VIDEO";
const CAPTURE_IMAGE = "CAPTURE_IMAGE";

let imageCapture;

const MEDIA_CONSTRAINTS = {
	audio: true,
	video: true,
};



/*
	TO DO
	1. Use mozilla friendly image capture method
	2. Show photo shot for 2 seconds over top of the video tag
	3. Push to GIT

*/
const view = (state, { updateState, dispatch }) => {

	let {properties, videoInputs, defaultVideoId } = state;
	return (
		<div className='main_container'>
			{defaultVideoId==null ? (
				<img 
				src={camera_icon} 
				alt="Video Thumbnail" 
				className='no_video_icon'
 />
 ) : (
				<div className='canvas_container' >
					<video></video>
					{properties.showTrigger==true && (
						<button on-click={()=>dispatch("CAPTURE_IMAGE")}></button>
					)}

				</div>

			)}
			<canvas></canvas>
		</div>
	)
};

createCustomElement('x-1822728-loop-91-camera-box', {
	renderer: { type: snabbdom },
	view,
	actionHandlers: {
		[COMPONENT_DOM_READY]: ({ state, dispatch, updateState, host }) => {
			navigator.mediaDevices
				.getUserMedia(MEDIA_CONSTRAINTS)
				.then((stream) => {
					// getting a list of all available video sources
					if (!navigator.mediaDevices?.enumerateDevices) {
						console.log("enumerateDevices() not supported.");
					} else {
						let videoInputs = [];
						navigator.mediaDevices
							.enumerateDevices()
							.then((devices) => {
								devices
									.filter(device => device.kind == "videoinput")
									.forEach((device) => {
										console.log("Found a device", device);
										videoInputs.push({
											label: device.label,
											deviceId: device.deviceId
										});
									});

								if (videoInputs.length > 0) {
									updateState({
										"videoInputs": videoInputs,
										"defaultVideoId" : videoInputs[0].deviceId
									});

									dispatch("CAMERA_DETECTED",{
										"camera_ids":videoInputs
									});
									if (state.properties.useFirstCamera==true){
										window.setTimeout(()=>{
											dispatch(SHOW_CAMERA_VIDEO);
										});
									}

								}
							})
							.catch((err) => {
								console.error(`${err.name}: ${err.message}`);
							});
					}
				})
				.catch((err) => {
					console.log("User denied permissions");
				});

		},
		[SHOW_CAMERA_VIDEO] : ({state,dispatch,updateState,host})=> {
			const video = host.shadowRoot.querySelector("video");
			navigator
				.mediaDevices
				.getUserMedia({
					video : {
						deviceId : {
							exact : state.defaultVideoId
						}
					}
				})
				.then((stream) => {
						video.srcObject = stream;
						video.onloadedmetadata = () => {
							video.play();
						};
				});
		},
		[CAPTURE_IMAGE] : ({host, dispatch})=>{
			const video = host.shadowRoot.querySelector("video");
			const canvas = host.shadowRoot.querySelector("canvas");
			const computedStyle = getComputedStyle(video);
			canvas.height = computedStyle.height.replace("px","");
			canvas.width = computedStyle.width.replace("px","");
			const context = canvas.getContext("2d");
			canvas.style.display = "block";
			context.clearRect(0,0,canvas.width,canvas.height);
			context.drawImage(video,0,0,canvas.width,canvas.height);
			const dataurl = canvas.toDataURL("image/png",.99);
			dispatch("IMAGE_CAPTURED",
				{
				"dataurl":dataurl
			});
			setTimeout(() => {
				canvas.style.display = "none";
			}, 1000);

		},
		[COMPONENT_PROPERTY_CHANGED] : ({state, action : {payload}, dispatch, updateState}) => {
			if (payload.name == "cameraTrigger"){
				// user has triggered camera , we shall click the photo
				dispatch(CAPTURE_IMAGE);
			}

			if (payload.name=="cameraId"){
				console.log("CameraID was changed to ", payload.value)
				updateState({
					"defaultVideoId":payload.value
				});

				dispatch(SHOW_CAMERA_VIDEO);
			}
		}

	},
	setInitialState() {
		return {
			"videoInputs": [{
				label:"No camera available",
				deviceId:null
			}],
			defaultVideoId : null
		};
	},
	styles,
	properties : {
		cameraTrigger : {
			schema : {
				"type":"string",
			},
			default : "090"
		},
		useFirstCamera : {
			schema : {
				"type":"boolean"
			},
			default: true
		},
		cameraId : {
			schema : {
				"type":"string"
			},
			default : ""
		},
		showTrigger : {
			schema : {
				"type":"boolean"
			},
			default : true
		}
	}
});
